content.content:
 1→{# A basic example for a project-wide macro to cast a column uniformly #}
 2→
 3→{% macro cents_to_dollars(column_name) -%}
 4→    {{ return(adapter.dispatch('cents_to_dollars')(column_name)) }}
 5→{%- endmacro %}
 6→
 7→{% macro default__cents_to_dollars(column_name) -%}
 8→    ({{ column_name }} / 100)::numeric(16, 2)
 9→{%- endmacro %}
10→
11→{% macro postgres__cents_to_dollars(column_name) -%}
12→    ({{ column_name }}::numeric(16, 2) / 100)
13→{%- endmacro %}
14→
15→{% macro bigquery__cents_to_dollars(column_name) %}
16→    round(cast(({{ column_name }} / 100) as numeric), 2)
17→{% endmacro %}
18→
19→{% macro fabric__cents_to_dollars(column_name) %}
20→    cast({{ column_name }} as numeric(16,2)) / 100
21→{% endmacro %}
22→

1→{% macro generate_schema_name(custom_schema_name, node) -%}
2→    {%- if custom_schema_name is not none -%}
3→        {{ custom_schema_name | trim }}
4→    {%- else -%}
5→        {{ target.schema }}
6→    {%- endif -%}
7→{%- endmacro %}
8→

